function BoundInput({ name, label, control }) {
  const field = useFormFieldBinding<string>({ name, control })
  return (
    <FormField label={label} error={field.error}>
      <Input
        value={field.value ?? ""}
        onChange={(event) => field.onValueChange(event.target.value)}
        onBlur={field.onBlur}
      />
    </FormField>
  )
}

